const item = $input.first().json;

const step = String(item.step ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, '')
  .toLowerCase();

const rawMessage = String($node["Extract Message Data"].json["message"] ?? '').trim();

const message = rawMessage
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim()
  .toLowerCase();

let updateFields = {};
let nextStep = step;
let response = '';
let status = String(item.status ?? 'em_andamento');

const onlyDigits = (value) => String(value ?? '').replace(/\D/g, '');

const simNao = (value) => {
  if (['1', 'sim', 's'].includes(value)) return 'Sim';
  if (['2', 'nao', 'não', 'n'].includes(value)) return 'Não';
  return value;
};

const formatCPF = (value) => {
  const cpf = onlyDigits(value);
  if (cpf.length !== 11) return value ?? '';
  return cpf.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
};

const formatCEP = (value) => {
  const cep = onlyDigits(value);
  if (cep.length !== 8) return value ?? '';
  return cep.replace(/(\d{5})(\d{3})/, '$1-$2');
};

const pergunta = {
  inicio: 'Oi! Vamos começar sua cotação 🚗\n\nO seguro é para você ou para outra pessoa?\n\nResponda:\n1. Para mim\n2. Para outra pessoa',
  nome: 'Qual é o seu primeiro nome?',
  sobrenome: 'Agora me informe seu sobrenome:',
  cpf: 'Qual é o seu CPF?\n\nPode enviar apenas os números ou no formato:\n000.000.000-00',
  placa: 'Qual é a placa do veículo?\n\nExemplos:\nABC1234 ou ABC1D23',
  cep: 'Qual é o CEP de pernoite do veículo?\n\nExemplo: 15500-000',
  tipo_moradia: 'Você mora em casa ou apartamento?\n\nResponda:\n1. Casa\n2. Apartamento',
  ano_modelo: 'Qual é o ano/modelo do veículo?\n\nExemplo: 2022/2023',
  quase_final: 'Estamos quase acabando...',
  under_26: 'Existe algum condutor com menos de 26 anos?\n\nResponda:\n1. Sim\n2. Não',
  uso_veiculo: 'O veículo é utilizado para lazer/ida e volta ao trabalho ou de forma profissional?\n\nResponda:\n1. Lazer/ida e volta ao trabalho\n2. De forma profissional',
  detalhe_uso_profissional: 'Você utiliza para Uber, aplicativo, entregas ou prestação de serviço?',
  is_insured: 'Atualmente o veículo possui seguro?\n\nResponda:\n1. Sim\n2. Não',
  apolice: 'Envie a apólice atual em PDF ou foto.'
};

const getPergunta = (stepName) => pergunta[String(stepName ?? '').toLowerCase()] ?? 'Vamos continuar de onde paramos.';

const respostaOpcao = (value, opcoes) => {
  if (opcoes[value]) return opcoes[value];
  return null;
};

const montarResumoCliente = (data) => {
  const detalheUso =
    data.detalhe_uso_profissional &&
    data.detalhe_uso_profissional !== 'null'
      ? `🧾 Detalhe uso profissional: ${data.detalhe_uso_profissional}\n`
      : '';

  const apolice =
    data.apolice_recebida &&
    data.apolice_recebida !== 'Não se aplica' &&
    data.apolice_recebida !== 'null'
      ? `📄 Apólice recebida: ${data.apolice_recebida}\n`
      : '';

  return `📋 RESUMO DA SUA COTAÇÃO

👤 Nome: ${data.nome ?? ''} ${data.sobrenome ?? ''}
🪪 CPF: ${formatCPF(data.cpf)}
🚗 Placa: ${data.placa ?? ''}
📍 CEP: ${formatCEP(data.cep)}
🏠 Moradia: ${data.tipo_moradia ?? ''}
📅 Ano/modelo: ${data.ano_modelo ?? ''}
👥 Condutor menor de 26 anos: ${simNao(String(data.under_26 ?? '').toLowerCase())}
🚘 Uso do veículo: ${data.uso_veiculo ?? ''}
${detalheUso}🛡️ Possui seguro atual: ${simNao(String(data.is_insured ?? '').toLowerCase())}
${apolice}
✅ Cotação enviada com sucesso!

Recebemos suas informações e já encaminhamos sua solicitação para nossa equipe.

📞 Em breve um consultor entrará em contato pelo WhatsApp para apresentar as melhores opções de seguro para o seu perfil e veículo.

Obrigado pela confiança! 🚗🛡️`;
};

const montarResumoLeo = (data) => {
  const detalheUso =
    data.detalhe_uso_profissional &&
    data.detalhe_uso_profissional !== 'null'
      ? data.detalhe_uso_profissional
      : 'Nao informado';

  const apolice =
    data.apolice_recebida &&
    data.apolice_recebida !== 'Não se aplica' &&
    data.apolice_recebida !== 'null'
      ? data.apolice_recebida
      : 'Nao se aplica';

  return `NOVA COTACAO FINALIZADA

Cliente: ${data.nome ?? ''} ${data.sobrenome ?? ''}
Telefone: ${data.phone ?? ''}
CPF: ${formatCPF(data.cpf)}
Placa: ${data.placa ?? ''}
CEP: ${formatCEP(data.cep)}
Moradia: ${data.tipo_moradia ?? ''}
Ano/modelo: ${data.ano_modelo ?? ''}
Menor de 26 anos: ${simNao(String(data.under_26 ?? '').toLowerCase())}
Uso do veiculo: ${data.uso_veiculo ?? ''}
Detalhe uso profissional: ${detalheUso}
Possui seguro atual: ${simNao(String(data.is_insured ?? '').toLowerCase())}
Apolice recebida: ${apolice}

Entrar em contato com o cliente.`;
};

const isValidCPF = (cpf) => {
  const cleaned = onlyDigits(cpf);
  if (cleaned.length !== 11) return false;
  if (/^(\d)\1{10}$/.test(cleaned)) return false;

  let sum = 0;
  for (let i = 0; i < 9; i++) sum += Number(cleaned[i]) * (10 - i);

  let firstDigit = (sum * 10) % 11;
  if (firstDigit === 10) firstDigit = 0;
  if (firstDigit !== Number(cleaned[9])) return false;

  sum = 0;
  for (let i = 0; i < 10; i++) sum += Number(cleaned[i]) * (11 - i);

  let secondDigit = (sum * 10) % 11;
  if (secondDigit === 10) secondDigit = 0;

  return secondDigit === Number(cleaned[10]);
};

const isValidCEP = (value) => onlyDigits(value).length === 8;

const isValidAnoModelo = (value) => {
  const match = String(value).match(/(19|20)\d{2}\s*\/?\s*(19|20)?\d{2}/);
  return Boolean(match);
};

const isValidPlaca = (value) => {
  const cleaned = String(value).toUpperCase().replace(/[^A-Z0-9]/g, '');
  const oldPlate = /^[A-Z]{3}\d{4}$/;
  const mercosul = /^[A-Z]{3}\d[A-Z]\d{2}$/;
  return oldPlate.test(cleaned) || mercosul.test(cleaned);
};

if (message === 'reiniciar' || message === 'nova cotacao' || message === 'nova cotação') {
  updateFields = {
    tipo_cliente: '',
    nome: '',
    sobrenome: '',
    cpf: '',
    placa: '',
    cep: '',
    ano_modelo: '',
    under_26: '',
    is_insured: '',
    tipo_moradia: '',
    uso_veiculo: '',
    detalhe_uso_profissional: '',
    apolice_recebida: '',
    apolice_media_id: null,
    apolice_tipo: null,
    leo_message: null,
    enviado_leo: false
  };

  nextStep = 'inicio';
  status = 'em_andamento';
  response = pergunta.inicio;
}

else if (step === 'finalizado') {
  response = 'Sua cotação já foi finalizada.\n\nSe quiser começar outra cotação, digite:\nNova cotação';
  nextStep = 'finalizado';
  status = 'finalizado';
}

else if (step === 'inicio') {
  const tipoCliente = respostaOpcao(message, {
    '1': 'Para mim',
    '2': 'Para outra pessoa',
    'eu': 'Para mim',
    'para mim': 'Para mim',
    'pra mim': 'Para mim',
    'outra pessoa': 'Para outra pessoa'
  });

  if (!tipoCliente) {
    response = `Resposta inválida.\n\n${pergunta.inicio}`;
    nextStep = step;
  } else {
    updateFields.tipo_cliente = tipoCliente;
    nextStep = 'nome';
    response = pergunta.nome;
  }
}

else if (step === 'nome') {
  if (rawMessage.length < 2) {
    response = `Nome inválido.\n\n${pergunta.nome}`;
    nextStep = step;
  } else {
    updateFields.nome = rawMessage;
    nextStep = 'sobrenome';
    response = `Prazer, ${rawMessage}!\n\n${pergunta.sobrenome}`;
  }
}

else if (step === 'sobrenome') {
  if (rawMessage.length < 2) {
    response = `Sobrenome inválido.\n\n${pergunta.sobrenome}`;
    nextStep = step;
  } else {
    updateFields.sobrenome = rawMessage;
    nextStep = 'cpf';
    response = pergunta.cpf;
  }
}

else if (step === 'cpf') {
  if (!isValidCPF(rawMessage)) {
    response = 'CPF inválido.\n\nPor favor, envie um CPF válido com 11 dígitos.';
    nextStep = step;
  } else {
    updateFields.cpf = onlyDigits(rawMessage);
    nextStep = 'placa';
    response = pergunta.placa;
  }
}

else if (step === 'placa') {
  if (!isValidPlaca(rawMessage)) {
    response = 'Placa inválida.\n\nEnvie uma placa válida, como:\nABC1234 ou ABC1D23';
    nextStep = step;
  } else {
    updateFields.placa = rawMessage.toUpperCase().replace(/[^A-Z0-9]/g, '');
    nextStep = 'cep';
    response = pergunta.cep;
  }
}

else if (step === 'cep') {
  if (!isValidCEP(rawMessage)) {
    response = 'CEP inválido.\n\nEnvie um CEP com 8 dígitos.\nExemplo: 15500-000';
    nextStep = step;
  } else {
    updateFields.cep = onlyDigits(rawMessage);
    nextStep = 'tipo_moradia';
    response = pergunta.tipo_moradia;
  }
}

else if (step === 'tipo_moradia') {
  const moradia = respostaOpcao(message, {
    '1': 'Casa',
    '2': 'Apartamento',
    'casa': 'Casa',
    'apartamento': 'Apartamento',
    'apto': 'Apartamento'
  });

  if (!moradia) {
    response = `Resposta inválida.\n\n${pergunta.tipo_moradia}`;
    nextStep = step;
  } else {
    updateFields.tipo_moradia = moradia;
    nextStep = 'ano_modelo';
    response = pergunta.ano_modelo;
  }
}

else if (step === 'ano_modelo') {
  if (!isValidAnoModelo(rawMessage)) {
    response = 'Ano/modelo inválido.\n\nEnvie no formato:\n2022/2023';
    nextStep = step;
  } else {
    updateFields.ano_modelo = rawMessage;
    nextStep = 'under_26';
    response = `${pergunta.quase_final}\n\n${pergunta.under_26}`;
  }
}

else if (step === 'under_26') {
  const menor26 = respostaOpcao(message, {
    '1': 'Sim',
    '2': 'Não',
    'sim': 'Sim',
    'nao': 'Não',
    'não': 'Não'
  });

  if (!menor26) {
    response = `Resposta inválida.\n\n${pergunta.under_26}`;
    nextStep = step;
  } else {
    updateFields.under_26 = menor26;
    nextStep = 'uso_veiculo';
    response = pergunta.uso_veiculo;
  }
}

else if (step === 'uso_veiculo') {
  const uso = respostaOpcao(message, {
    '1': 'Lazer/ida e volta ao trabalho',
    '2': 'De forma profissional',
    'lazer': 'Lazer/ida e volta ao trabalho',
    'trabalho': 'Lazer/ida e volta ao trabalho',
    'profissional': 'De forma profissional'
  });

  if (!uso) {
    response = `Resposta inválida.\n\n${pergunta.uso_veiculo}`;
    nextStep = step;
  } else {
    updateFields.uso_veiculo = uso;

    if (uso === 'De forma profissional') {
      nextStep = 'detalhe_uso_profissional';
      response = pergunta.detalhe_uso_profissional;
    } else {
      nextStep = 'is_insured';
      response = pergunta.is_insured;
    }
  }
}

else if (step === 'detalhe_uso_profissional') {
  if (rawMessage.length < 2) {
    response = `Resposta inválida.\n\n${pergunta.detalhe_uso_profissional}`;
    nextStep = step;
  } else {
    updateFields.detalhe_uso_profissional = rawMessage;
    nextStep = 'is_insured';
    response = pergunta.is_insured;
  }
}

else if (step === 'is_insured') {
  const possuiSeguro = respostaOpcao(message, {
    '1': 'Sim',
    '2': 'Não',
    'sim': 'Sim',
    'nao': 'Não',
    'não': 'Não'
  });

  if (!possuiSeguro) {
    response = `Resposta inválida.\n\n${pergunta.is_insured}`;
    nextStep = step;
  } else {
    updateFields.is_insured = possuiSeguro;

    if (possuiSeguro === 'Sim') {
      nextStep = 'apolice';
      response = pergunta.apolice;
    } else {
      updateFields.apolice_recebida = 'Não se aplica';
      updateFields.apolice_media_id = null;
      updateFields.apolice_tipo = null;
      updateFields.enviado_leo = false;

      const finalData = {
        ...item,
        ...updateFields
      };

      nextStep = 'finalizado';
      status = 'finalizado';
      response = montarResumoCliente(finalData);
      updateFields.leo_message = montarResumoLeo(finalData);
    }
  }
}

else if (step === 'apolice') {
  const messageType = String($node["Extract Message Data"].json["message_type"] ?? '');
  const mediaId = String($node["Extract Message Data"].json["media_id"] ?? '');

  if (!['image', 'document'].includes(messageType) || !mediaId) {
    response = 'Por favor, envie a apólice em PDF ou foto.';
    nextStep = 'apolice';
  } else {
    updateFields.apolice_recebida = 'Recebida';
    updateFields.apolice_media_id = mediaId;
    updateFields.apolice_tipo = messageType;
    updateFields.enviado_leo = false;

    const finalData = {
      ...item,
      ...updateFields
    };

    nextStep = 'finalizado';
    status = 'finalizado';
    response = montarResumoCliente(finalData);
    updateFields.leo_message = montarResumoLeo(finalData);
  }
}

else {
  response = `Não entendi direito.\n\n${getPergunta(step)}`;
  nextStep = step;
}

return [
  {
    json: {
      ...item,
      ...updateFields,
      step: nextStep,
      status,
      response
    }
  }
];

const phone = String($node["Extract Message Data"].json["phone"] ?? '').trim();

return [
  {
    json: {
      cotacao_id: `cot_${Date.now()}`,
      phone,
      step: 'inicio',
      status: 'em_andamento',

      tipo_cliente: '',
      nome: '',
      sobrenome: '',
      cpf: '',
      genero: '',

      placa: '',
      cep: '',
      ano_modelo: '',

      under_26: '',
      is_insured: '',

      enviado_leo: false,

      response: 'Oi! Vamos começar sua cotação 🚗\n\nO seguro é para você ou para outra pessoa?\n\nResponda:\n1. Para mim\n2. Para outra pessoa'
    }
  }
];

const query = $json.query || {};

return [
  {
    json: {
      challenge: query["hub.challenge"],
    },
  },
];
